-- Oracle-flavored reference DDL; no live DB connection in demo
CREATE TABLE DEO_ENGAGEMENT (ENGAGEMENT_ID NUMBER PRIMARY KEY, CLIENT_NAME VARCHAR2(100), DELIVERY_MANAGER VARCHAR2(100), STATUS VARCHAR2(20));
CREATE TABLE DEO_MILESTONE (MILESTONE_ID NUMBER PRIMARY KEY, ENGAGEMENT_ID NUMBER REFERENCES DEO_ENGAGEMENT(ENGAGEMENT_ID), TITLE VARCHAR2(200), OWNER_ID VARCHAR2(50), DUE_DATE DATE, STATUS VARCHAR2(20), UPDATED_AT TIMESTAMP);
CREATE TABLE DEO_TIMESHEET (ENTRY_ID NUMBER PRIMARY KEY, ENGAGEMENT_ID NUMBER REFERENCES DEO_ENGAGEMENT(ENGAGEMENT_ID), EMPLOYEE_ID VARCHAR2(50), WORK_DATE DATE, HOURS NUMBER(4,2), APPROVAL_STATUS VARCHAR2(20));
CREATE TABLE DEO_AUDIT (AUDIT_ID NUMBER PRIMARY KEY, ENTITY_TYPE VARCHAR2(30), ENTITY_ID NUMBER, ACTION VARCHAR2(50), ACTOR_ID VARCHAR2(50), ACTION_AT TIMESTAMP);
